// Siempre el mismo lugar para la misma pregunta: sembrar dos veces da lo mismo.
function hash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
const VF = ["Verdadero", "Falso"];

// El tiempo: 30 s, y 60 s si hay mucho que leer.
function tiempoDe(p) {
  const largo = p.texto.length + p.correcta.length + p.otras.reduce((a, o) => a + o.length, 0);
  return largo > 200 ? 60 : 30;
}

function armar(p) {
  const todas = [p.correcta, ...p.otras];
  let opciones, correcta;
  if (todas.length === 2 && VF.includes(todas[0]) && VF.includes(todas[1])) {
    opciones = VF.slice();
    correcta = VF.indexOf(p.correcta);
  } else {
    // El lugar de la correcta sale del texto; las demás, en el orden escrito.
    correcta = hash(p.texto) % todas.length;
    opciones = p.otras.slice();
    opciones.splice(correcta, 0, p.correcta);
  }
  return { texto: p.texto, opciones, correcta, tiempo: tiempoDe(p), fen: null };
}

const cuestionarios = () => LISTOS.map((c) => ({ titulo: c.titulo, nivel: c.nivel, preguntas: c.preguntas.map(armar) }));

/* Una sentencia por nivel, con cada pregunta como [texto, opciones, correcta,
   tiempo]: la base arma el objeto. Así el SQL pesa un cuarto menos y cabe en
   el editor de Supabase de a un nivel por vez (cada sentencia es completa). */
function sql() {
  const partes = [
    "-- Generado por herramientas/cuestionarios-listos.js: no se edita a mano.",
    "delete from public.cuestionarios where listo;",
  ];
  ["inicial", "intermedio", "avanzado"].forEach((nivel) => {
    const filas = cuestionarios().filter((c) => c.nivel === nivel).map((c) => "($q$" + c.titulo + "$q$, $q$"
      + JSON.stringify(c.preguntas.map((p) => [p.texto, p.opciones, p.correcta, p.tiempo])) + "$q$::jsonb)");
    partes.push("with d(titulo, p) as (values\n" + filas.join(",\n") + ")\n"
      + "insert into public.cuestionarios (titulo, nivel, listo, profesor_id, preguntas)\n"
      + "select titulo, '" + nivel + "', true, null, (select jsonb_agg(jsonb_build_object('texto', e->>0, 'opciones', e->1, "
      + "'correcta', (e->>2)::int, 'tiempo', (e->>3)::int, 'fen', null) order by o) from jsonb_array_elements(p) with ordinality x(e, o)) from d;");
  });
  return partes.join("\n") + "\n";
}

module.exports = { LISTOS, armar, cuestionarios, sql };

if (require.main === module) {
  const dir = path.join(__dirname, "cuestionarios");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, "semilla.sql"), sql());
  const n = LISTOS.reduce((a, c) => a + c.preguntas.length, 0);
  console.log("herramientas/cuestionarios/semilla.sql: " + LISTOS.length + " cuestionarios, " + n + " preguntas.");
}
